"""Stage generated bytes globally; publish Result and file references in one transaction."""

import tempfile
from dataclasses import dataclass
from io import BytesIO
from pathlib import Path

from shotmill.application.file_library import FileLibrary
from shotmill.domain.entities import Result, new_id
from shotmill.domain.files import FileReference, StoredFile
from shotmill.domain.providers import GeneratedOutput
from shotmill.domain.repositories import UnitOfWork
from shotmill.media.file_storage import FileStorage
from shotmill.media.previews import result_with_preview
from shotmill.media.storage import MediaStorage


@dataclass
class CollectedResult:
    result: Result
    files: list[tuple[StoredFile, FileReference]]
    storage: FileStorage

    def register_files(self, uow: UnitOfWork) -> None:
        # Collection precedes the reserved publication transaction. Revalidate
        # every object before publishing any of its logical references.
        for file, _ in self.files:
            self.storage.verify(file)
        for file, reference in self.files:
            uow.files.register(file)
            uow.files.bind(reference)


class ResultFileCollector:
    def __init__(self, library: FileLibrary):
        self.library = library

    def collect(
        self, project_id: str, task_id: str, job_id: str, output: GeneratedOutput,
    ) -> CollectedResult:
        stream = BytesIO(output.content) if isinstance(output.content, bytes) else output.content
        file = self.library.storage.put(stream)
        result_id = new_id("result")
        relative = f"shared/result/{result_id}/output"
        url = MediaStorage.media_url(project_id, relative)
        result = Result(
            id=result_id, project_id=project_id, task_id=task_id, job_id=job_id,
            video_url=url,
            preview_url=url if (output.content_type or "").startswith("image/") else None,
            metadata={**output.metadata, "contentType": output.content_type,
                      "originalFilename": output.filename},
        )
        files = [(file, FileReference(
            "project", project_id, "result", result_id, "output", file.sha256,
            output.filename, output.content_type,
        ))]
        staging = self.library.storage.managed.resolve("staging")

        def resolve_pending(owner_project: str, pending_path: str) -> Path:
            if owner_project != project_id or pending_path != relative:
                raise ValueError("Unknown unpublished result reference")
            return self.library.storage.resolve(file)

        # Derived posters are private until every file has been collected. No
        # permanent project-local duplicate or premature DB reference is needed.
        with tempfile.TemporaryDirectory(prefix="result-preview-", dir=staging) as directory:
            media = MediaStorage(Path(directory), shared_resolver=resolve_pending)
            result = result_with_preview(result, media)
            if result.preview_url and result.preview_url != url:
                prefix = f"/media/{project_id}/"
                if not result.preview_url.startswith(prefix):
                    raise ValueError("Unexpected generated preview location")
                path = media.resolve(project_id, result.preview_url[len(prefix):])
                with path.open("rb") as preview:
                    poster = self.library.storage.put(preview)
                files.append((poster, FileReference(
                    "project", project_id, "result", result_id, "preview", poster.sha256,
                    "preview.png", "image/png",
                )))
                result.preview_url = MediaStorage.media_url(
                    project_id, f"shared/result/{result_id}/preview",
                )
        return CollectedResult(result, files, self.library.storage)
